using System;

namespace StdbModule;

public static partial class FrenchQuotes
{
    public static class HonorédeBalzac
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Il existe un lien secret entre toutes les femmes, comme entre tous les prêtres d'une même religion. Elles se haïssent, mais elles se protégent.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Nous sommes allés chercher de la laine et nous allons revenir tondus.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "L'amour est la seule passion qui ne souffre ni passé ni avenir.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "la joie ne peut éclater que parmi les gens qui se sentent égaux.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Nous avons tous la prétention de souffrir beaucoup plus que les autres.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Le despotisme fait illégalement de grandes choses, la liberté ne se donne même pas la peine d'en faire légalement de très petites.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "L’écrivain doit être familiarisé avec tous les effets, toutes les natures. Il est obligé d’avoir en lui je ne sais quel miroir concentrique où, suivant sa fantaisie, l’univers vient se réfléchir.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Mais, sachez-le bien, à peine avez-vous fait un pas vers le tapis vert, déjà votre chapeau ne vous appartient pas plus que vous ne vous appartenez à vous-même : vous êtes au jeu, vous, votre fortune, votre coiffe, votre canne et votre manteau.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Vouloir nous brûle et Pouvoir nous détruit; mais SAVOIR laisse notre faible organisation dans un perpétuel état de calme.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "La pensée est la clef de tous les trésors, elle procure les joies de l'avare sans en donner les soucis.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Le journalisme, vois-tu, c'est la religion des sociétés modernes, et il y a progrès.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Je dus [...] aller voir des hommes d'État, [...] les séduire, eux, leurs femmes, leurs valets, leurs chiens [...].", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Les orphelins recueillis par la charité publique ont au moins pour avenir le champ de bataille, pour père le gouvernement ou le procureur du roi, pour refuge un hospice. Moi, je n'avais rien !", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Devenant tout à coup physiologiste par instinct, il rendait compte des ressemblances animales inscrites sur les figures humaines, par des analogies primordiales et par le mouvement ascendant de la création.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Le sot n’est-il pas celui qui ne justifie pas la bonne opinion qu’il prend de lui-même ?", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Religion veut dire LIEN, et certes le culte, ou autrement dit la religion exprimée, constitue la seule force qui puisse relier les Espèces sociales et leur donner une forme durable.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Si la lumière est le premier amour de la vie, l'amour n'est-il pas la lumière du cœur ?", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "La gloire est le soleil des morts, de ton vivant, tu seras malheureux comme tout ce qui fut grand, et tu ruineras tes enfants.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "La société ne pratique aucune des vertus qu’elle demande aux hommes, elle commet des crimes à toute heure, mais elle les commet en paroles ; elle prépare les mauvaises actions par la plaisanterie, comme elle dégrade le beau par le ridicule ; elle se moque des fils qui pleurent trop leurs pères, elle anathématise ceux qui ne les pleurent pas assez ; puis elle s’amuse, elle ! à soupeser les cadavres avant qu’ils soient refroidis.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Plus nos lois tendront à une impossible égalité, plus nous nous en écarterons par les mœurs.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "l’esprit français, le plus vif, le plus acéré de tous les instruments intelligentiels", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "le journaliste est une pensée en marche comme le soldat en guerre", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "La seule épigramme permise à la Misère est d' obliger la Justice et la Bienfaisance à des dénis injustes. Quand les malheureux ont convaincu la Société de mensonge, ils se rejettent plus vivement dans le sein de Dieu.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Où en étais-je ? dit le colonel avec la naïveté d’un enfant ou d’un soldat, car il y a souvent de l’enfant dans le vrai soldat, et presque toujours du soldat chez l’enfant, surtout en France.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Le malheur est une espèce de talisman dont la vertu consiste à corroborer notre constitution primitive : il augmente la défiance et la méchanceté chez certains hommes, comme il accroît la bonté de ceux qui ont un cœur excellent.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Le vieux soldat était calme, immobile, presque distrait. Malgré ses haillons, malgré la misère empreinte sur sa physionomie , elle déposait d'une noble fierté. Son regard avait une expression de stoïcisme qu'un magistrat n'aurait pas dû méconnaître; mais, dès qu'un homme tombe entre les mains de la justice, il n'est plus qu'un être moral, une question de Droit ou de Fait, comme aux yeux des statisticiens il devient un chiffre.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Il existe dans notre société trois hommes, le Prêtre, le Médecin et l'Homme de justice, qui ne peuvent pas estimer le monde. Ils ont des robes noires, peut-être parce qu'ils portent le deuil de toutes les vertus, de toutes les illusions.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "[...] Toutes les horreurs que les romanciers croient inventer sont toujours au-dessous de la vérité.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "A Paris, quand certaines gens vous voient mettre le pied à l'étrier, les uns vous tirent par le pan de votre habit, les autres lâchent la boucle de la sous-ventrière pour que vous vous cassiez la tête en tombant; celui-ci vous deferre le cheval, celui-là vous vole le fouet : le moins traître est celui que vous voyez venir pour vous tirer un coup de pistolet à bout portant. Vous avez assez de talent, mon cher enfant, pour connaître bientôt la bataille horrible, incessante, que la médiocrité livre à l'homme supérieur.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Les mythes modernes sont encore moins compris que les mythes anciens, quoique nous soyons dévorés par les mythes.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "l’amour-propre est un escroc qui ne manque jamais sa dupe.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Le génie procède de deux manières : ou il prend son bien comme Napoléon et Molière aussitôt qu’il le voit, ou il attend qu’on le vienne chercher quand il s’est patiemment révélé.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Les lois sont des toiles d’araignées à travers lesquelles passent les grosses mouches et où restent les petites.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Dans ce produit bizarre, vous eussiez reconnu l'actionnaire par excellence, croyant à toutes les nouvelles que la presse périodique baptise de son encre, et qui a tout dit en disant : Lisez le journal !", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "En France, ce qu’il y a de plus national, est la vanité. La masse des vanités blessées y a donné soif d’égalité.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Privilége semblable à celui de la noblesse, la beauté ne se peut acquérir, elle est partout reconnue, et vaut souvent plus que la fortune et le talent, elle n’a besoin que d’être montrée pour triompher, on ne lui demande que d’exister.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Quand un artiste a le malheur d’être plein de la passion qu’il veut exprimer, il ne saurait la peindre, car il est la chose même au lieu d’en être l’image. L’art procède du cerveau et non du cœur. Quand votre sujet vous domine, vous en êtes l’esclave et non le maître.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "L’épicier est entraîné vers son commerce par une force attractive égale a la force de répulsion qui en éloigne les artistes.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Ses malheurs au Texas, son séjour à New-York, pays où la spéculation et l’individualisme sont portés au plus haut degré, où la brutalité des intérêts arrive au cynisme, où l’homme, essentiellement isolé, se voit contraint de marcher dans sa force et de se faire à chaque instant juge dans sa propre cause, où la politesse n’existe pas.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Il lisait d’ailleurs beaucoup, il se donnait cette profonde et sérieuse instruction que l’on ne tient que de soi-même, et à laquelle tous les gens de talent se sont livrés entre vingt et trente ans.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Jadis on ne demandait que de l’intérêt au roman ; quant au style, personne n’y tenait, pas même l’auteur ; quant à des idées, zéro ; quant à la couleur locale, néant. Insensiblement le lecteur a voulu du style, de l’intérêt, du pathétique, des connaissances positives ; il a exigé les cinq sens littéraires : l’invention, le style, la pensée, le savoir, le sentiment ; puis la Critique est venue, brochant sur le tout.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Néanmoins il n’existe pas de grand talent sans une grande volonté. Ces deux forces jumelles sont nécessaires à la construction de l’immense édifice d’une gloire. Les hommes d’élite maintiennent leur cerveau dans les conditions de la production, comme jadis un preux avait ses armes toujours en état.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "La volonté peut et doit être un sujet d’orgueil bien plus que le talent. Si le talent a son germe dans une prédisposition cultivée, le vouloir est une conquête faite à tout moment sur les instincts, sur les goûts domptés, refoulés, sur les fantaisies et les entraves vaincues, sur les difficultés de tout genre héroïquement surmontées.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "En conceptions bizarres, l’imagination des femmes va plus loin que celle des hommes, témoin le Frankenstein de mistress Shelley, le Leone Leoni de George Sand, les œuvres d’Anne Radcliffe et le Nouveau Prométhée de Camille Maupin.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "La femme porte le désordre dans la société par la passion.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "L’impression est aux manuscrits ce que le théâtre est aux femmes elle met en lumière les beautés et les défauts ; elle tue aussi bien qu’elle fait vivre ; une faute saute alors aux yeux aussi vivement que les belles pensées.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Le roman, qui veut le sentiment, le style et l’image, est la création moderne la plus immense. Il succède à la comédie qui, dans les mœurs modernes, n’est plus possible avec ses vieilles lois.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "le Poète qui semble ne rien faire et qui néanmoins règne sur l’Humanité quand il a su la peindre.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Bettina mourante inocula donc l’amour à sa sœur, elle lui communiqua cette lèpre de l’âme.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Ni lord Byron, ni Goethe, ni Walter Scott, ni Cuvier, ni l’inventeur ne s’appartiennent, ils sont les esclaves de leur idée ; et cette puissance mystérieuse est plus jalouse qu’une femme, elle les absorbe, elle les fait vivre et les tue à son profit.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "A Paris, un nom devient une propriété commerciale, et finit par constituer une sorte de noblesse d’enseigne.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "L’opinion d’un artiste doit être la foi dans les œuvres… et son seul moyen de succès, le travail quand la nature lui a donné le feu sacré.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Quoique richement mise, elle épouvantait par les signes de méchanceté froide que présentait sa plate figure horriblement ridée, blanche et musculeuse. Marat, en femme et à cet âge, eût été, comme la Saint-Estève, une image vivante de la Terreur. Cette vieille sinistre offrait dans ses petits yeux clairs la cupidité sanguinaire des tigres. Son nez épaté, dont les narines agrandies en trous ovales soufflaient le feu de l'enfer, rappelait le bec des plus mauvais oiseaux de proie. Le génie de l'intrigue siégeait sur son front bas et cuel. Ses longs poils de barbe poussés au hazard dans tous les creux de son visage, annonçaient la virilité de ses projets. Quiconque eût vu cette femme aurait pensé que tous les peintres avaient manqué la Figure de Méphistophélès.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "En conservant dans quelques détails de sa mise une fidélité quand même aux modes de l'an 1806, ce passant rappelait l'Empire sans être par trop caricature. Pour les observateurs, cette finesse rend ces sortes d'évocations extrêmement précieuses. Mais cet ensemble de petites choses voulait l'attention analytique dont sont doués les connaisseurs en flânerie ; et, pour exciter le rire à distance, le passant devait offrir une de ces énormités à crever les yeux, comme on dit, et que les acteurs recherchent pour assurer le succès de leurs entrées. Ce vieillard, sec et maigre, portait un spencer couleur noisette sur un habit verdâtre à boutons de métal blanc !... Un homme en spencer, en 1844, c'est, voyez-vous, comme si Napoléon eût daigné ressusciter pour deux heures.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Concevoir, disait-il, c'est jouir, 'c'est fumer des cigarettes enchantées' ; mais sans l'exécution, tout s'en va en rêve et en fumée : 'Le travail constant, a-t-il dit encore, est la loi de l'art comme celle de la vie ; car l'art, c'est la création idéalisée. Aussi les grands artistes, les poètes, n'attendent-ils ni les commandes, ni les chalands ; ils enfantent aujourd'hui, demain, toujours. Il en résulte cette perpétuelle connaissance des difficultés qui les maintient en concubinage avec la Muse'.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Mon père m'a donné un cœur, mais vous l'avez fait battre.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Balzac à Eve Hanska, 19 octobre 1834 : Le dernier roman de Mme Dudevant est un conseil donné aux maris, qui gênent leurs femmes, de se tuer pour les laisser libres...", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "La Divine comédie est l'histoire de l'homme qui a vécu, 'La Comédie humaine' est l'histoire de l'homme qui vit.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Paris nous excite trop, nous autres gens ordinaires ; quels fourmilières d'idées devaient pulluler dans cet esprit, qui, multiplié par l'inspiration et par la science, apercevait dans un geste, dans un vêtement un caractère et une vie entière, les reliait à leur siècle, prévoyait leur avenir, les pénétrait en peintre, en médecin, en philosophe, et étendait le réseau infini de ses divinations involontaires à travers toutes les idées et tous les faits !", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Beaucoup de gens souffrent de le lire. Le style est pénible, surchargé; les idées s'encombrent et s'étouffent; les intrigues compliquées saisissent l'esprit de leur pince de fer; les passions accumulées, grondantes, flamboient comme une fournaise. Sous cette lueur fauve se détache avec un relief violent une multitude de figures grimaçantes, tourmentées, plus expressives, plus puissantes, plus vivantes que les physionomies réelles; parmi elles une vermine sale d'insectes humains, cloportes rampants, scolopendres hideux, araignées venimeuses nées dans la pourriture, acharnées à fouir, à déchirer, à entasser et à mordre; par-dessus tout des féeries éblouissantes, et le cauchemar douloureux et gigantesque de tous les rêves auxquels l'or, la science, l'art, la gloire et la puissance peuvent fournir.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Car les héros de l’Iliade ne vont qu’à votre cheville, ô Vautrin, ô Rastignac, ô Birotteau [...] et vous, ô Honoré de Balzac, vous le plus héroïque, le plus singulier, le plus romantique et le plus poétique parmi tous les personnages que vous avez tirés de votre sein !", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Si Balzac a fait de ce genre roturier [le roman de mœurs] une chose admirable, toujours curieuse et souvent sublime, c’est parce qu’il y a jeté tout son être. J’ai maintes fois été étonné que la grande gloire de Balzac fût de passer pour un observateur ; il m’avait toujours semblé que son principal mérite était d’être visionnaire, et visionnaire passionné. Tous ses personnages sont doués de l’ardeur vitale dont il était animé lui-même. Toutes ses fictions sont aussi profondément colorées que les rêves. Depuis le sommet de l’aristocratie jusqu’aux bas-fonds de la plèbe, tous les acteurs de sa Comédie sont plus âpres à la vie, plus actifs et rusés dans la lutte, plus patients dans le malheur, plus goulus dans la jouissance, plus angéliques dans le dévouement, que la comédie du vrai monde ne nous les montre. Bref, chacun, chez Balzac, même les portières, a du génie. Toutes les âmes sont des armes chargées de volonté jusqu’à la gueule. C’est bien Balzac lui-même. Et comme tous les êtres du monde extérieur s’offraient à l’œil de son esprit avec un relief puissant et une grimace saisissante, il a fait se convulser ses figures ; il a noirci leurs ombres et illuminé leurs lumières. Son goût prodigieux du détail, qui tient à une ambition immodérée de tout voir, de tout faire voir, de tout deviner, de tout faire deviner, l’obligeait d’ailleurs à marquer avec plus de force les lignes principales, pour sauver la perspective de l’ensemble. Il me fait quelquefois penser à ces aquafortistes qui ne sont jamais contents de la morsure, et qui transforment en ravines les écorchures principales de la planche. De cette étonnante disposition naturelle sont résultées des merveilles. Mais cette disposition se définit généralement : les défauts de Balzac. Pour mieux parler, c’est justement là ses qualités. Mais qui peut se vanter d’être aussi heureusement doué, et de ne pouvoir appliquer une méthode qui lui permette de revêtir, à coup sûr, de lumière et de pourpre la pure trivialité ? Qui peut faire cela ? Or, qui ne fait pas cela, pour dire la vérité, ne fait pas grand-chose.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Ce n’est pas le lieu de dire ici tout ce qu’était cette splendide et souveraine intelligence. Monsieur de Balzac était un des premiers parmi les plus grands, un des plus hauts parmi les meilleurs. Tous ses livres ne forment qu’un livre, livre vivant, lumineux, profond, où l’on voit aller et venir, marcher et se mouvoir, avec je ne sais quoi d’effaré et de terrible, mêlé au réel, toute notre civilisation contemporaine ; livre merveilleux que le poète a intitulé Comédie et qu’il aurait pu appeler Histoire ; qui prend toutes les formes et tous les styles ; qui dépasse Tacite et qui va jusqu’à Suétone ; qui traverse Beaumarchais et qui va jusqu’à Rabelais ; livre qui est l’observation et qui est l’imagination ; qui prodigue le vrai, l’intime, le bourgeois, le trivial, le matériel, et qui, par moment, laisse entrevoir le plus sombre et le plus tragique idéal.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "De Balzac va droit au but : il saisit corps à corps la société moderne ; il arrache à tous quelque chose ; aux uns l’illusion, aux autres l’espérance, à ceux-ci un cri, à ceux-là un masque. Il creuse et sonde l’homme, l’âme, le cœur, le cerveau, et par un trait de sa vigoureuse et libre nature, il se dégage souriant et serein de ces redoutables études qui produisaient la mélancolie chez Molière et la misanthropie chez Rousseau.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Voilà l'œuvre qu'il nous laisse, œuvre haute et solide, robuste entassement d'assises de granit, monument!œuvre du haut de laquelle resplendira désormais sa renommée. Les grands hommes font leur propre piédestal, l'avenir se charge de la statue.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Shakespeare seul a enfanté une humanité aussi large et aussi vivante.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "M. de Balzac, qui est un Tourangeau, est venu dans la contrée pour y acheter une petite propriété. Il s’est fait amener ici par un de mes voisins (M. de Margonne, châtelain de Saché). […] Malheureusement, il faisait un temps horrible, ce qui m’a obligée à le retenir à dîner. J’ai été polie, mais très réservée […] et j’ai été ravie quand il est parti. D’ailleurs, il ne m’a pas plu. Il est vulgaire de figure, de ton, et, je crois de sentiments ; sans doute, il a de l’esprit, mais il est sans verve ni facilité dans la conversation. Il y est même très lourd ; il nous a tous examinés et observés de la manière la plus minutieuse, M. de Talleyrand surtout.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Henri IV a conquis son royaume ville à ville. M. de Balzac a conquis son public maladif infirmités par infirmités (aujourd'hui les femmes de trente ans, demain celles de cinquante, après-demain les chlorotiques, dans ''Claës'' les contrefaits). Nulle part il est question de santé.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "J'admire comme les pensées de Balzac sont cosmologiquement justes. Telle est la part de sa forte tête dans ses créations qu'il entre dans les lieux communs et les rend vrais.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Balzac, c’est vous, c’est moi. En Balzac, je m’instruis beaucoup, non pas dans le vocabulaire des idées, mais dans celui des choses.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Balzac n’est pas un précurseur. Il est le créateur du monde moderne. C’est pourquoi tout jeune auteur d’aujourd’hui doit passer par lui.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Chacun sait que ce gros homme entendait faire une œuvre de défense et illustration des défenses sociales, voire de l'ordre moral, et qu'il a dressé, en fait, le plus formidable acte d'accusation qui ait jamais été lancé contre une civilisation.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Il reste prouvé que Balzac n’est pas seulement un grand poète, un faiseur dans le sens antique du mot, un vrai génie de création et de découverte, mais que de plus il est aussi, et il est surtout, un penseur d’une force et d’une variété infinies, qui se joue des généralités les plus hautes et ne se diminue pas dans les aperçus les plus fins. Pour tout dire en un mot, il restera prouvé qu’en hachant n’importe où, une page de Balzac, en tronquant cet ensemble merveilleux d’une page, on aura, avec des teintes nouvelles et l’originalité la plus profonde, quelque chose comme 'les Caractères' de La Bruyère, les 'Maximes' de La Rochefoucauld, les 'Pensées' de Vauvenargues et de Joubert, et les 'Aphorismes' de Bacon.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "[...] en 1835, Balzac, vraisemblablement encore troublé comme beaucoup par la vague déferlante de la première révolte absolue contre la condition humaine, éprouve le curieux besoin d'y mettre un terme avec son 'Melmoth réconcilié'. Qu'on ne s'y trompe pas : ce n'est pas une fantaisie littéraire ni un exercice de style, c'est une mesure d'ordre. Comme d'autres l'on fait de la dialectique, ici Balzac remet le roman sur ses pieds.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Au héros de Maturin dont Baudelaire disait : « Melmoth est une contradiction vivante. Il est sorti des conditions fondamentales de la vie ; ses organes ne supportent plus sa pensée », à ce hérault du mal qui n'a pas assez des siècles ni de l'univers pour répandre sa malédiction, Balzac offre la dépouille d'un caissier de banque parisien qui, pour subvenir à des besoins d'argent grandissants, vend son âme au diable. La dégringolade est aussi terrible que significative. C'est l'imaginaire vaincu par l'ordre rationnel, c'est la métaphysique ramenée à la niche des religions, c'est la poésie disparaissant pour longtemps du roman, dès lors tout entier acquis au réalisme, c'est-à-dire livré à une surveillance sans relâche qui a pour but de déterminer comme unique référent l'empire du réel.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "[...] ce n'est pas faute d'imagination mais bien par suite d'une farouche volonté de réalisme chez Balzac, que le malheureux caissier Castanier, devenu tout-puissant, se lasse très vite, trop vite de tout, à l'inverse de son modèle en malédiction, le 'Melmoth' de Maturin. [...] C'est que privés de leur dimension imaginaire, tous les plaisirs tournent court [...]. Quelques jours et trois pages sufisent à ce pauvre bougre pour revenir de toutes les jouissances et de tous les crimes, de tous les temps et de tous les pays. Rien d'étonnant à cela : ce pacte avec le diable, le caissier du dixième arrondissement ne l'a signé que pour se dégager d'énormes dettes, d'emprunts frauduleux, mais jamais, au grand jamais, pour sortir des limites de la condition humaine.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Castanier est un maudit économique comme on est aujourd'hui licencié économique. Balzac ne cherche d'ailleurs pas à nous tromper sur ce point : « Castanier n'avait pas, comme son maître, l'inextinguible puissance de haïr et de mal faire ; il se sentait démon, mais démon à venir, tandis que Satan est démon pour l'éternité. » D'où la constante maladresse de Balzac à nous raconter l'histoire de ce démon intérimaire, coincé entre l'absolu et ses colonnes de chiffres. 'Melmoth réconcilié', c'est Satan chez les ronds-de-cuir, pris au piège de leur manque d'envergure. Tragédie à rebours : rien n'est plus dérisoire que d'avoir de grands moyens pour de petits besoins. Nous voilà bien loin du combat du ciel et de l'enfer. Ce n'est pas Dieu, comme le suggère Balzac, qui a ici raison de Satan, mais la médiocrité du monde comme il va, du monde réel.\nLa situation est d'ailleurs aussi inconfortable pour l'auteur que pour son héros. Empêché par son projet réconciliateur de faire au satanisme la partie belle, c'est-à-dire de se laisser gagner par la démesure nécessaire à une telle évocation du mal, Balzac se trouve également incapable de s'emparer de la quotidienneté avec cette brutalité avide qui lui permet souvent de sertir les êtres et les choses d'un bref éclat d'éternité.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "En fait, le 'Melmoth' de Maturin et le 'Melmoth réconcilié' de Balzac sont des frères ennemis qui illustrent peut-être comme jamais encore cette opposition radicale du merveilleux et du fantastique : autant la soif d'absolu du premier Melmoth ne cesse-t-elle d'appeler en tout lieu, en tout moment, l'infini de l'espace imaginaire, autant le conte de Balzac, aboutissant à circonscrire, et du même coup à anéantir, la toute-puissance de son héros dans l'espace exigu d'un grenier de la rue Saint-Honoré, pourrait se confondre avec une opération essentiellement réductrice.\nPlus de fuite vers l'imaginaire, plus de recherche de l'absolu, toutes les passions de la créature humaine sont désormais localisables, mesurables. Le sens devient dès lors une valeur qui se contrôle comme les autres, plus que les autres. Et puisque la malédiction n'a plus cours, c'est justement tout ce qui échappe à l'évaluation réaliste qui se trouve par là même frappé de malédiction, c'est-à-dire de non-existence.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Aussi, en convertissant la dépossession métaphysique de Melmoth en simple besoin de possession pour le caissier Castanier, Balzac s'est-il improvisé le triste changeur de la rationalité en esthétique de l'offre et de la demande. Le réalisme constitue, sans aucun doute, le meilleur placement esthétique car il suppose un rendement idéologique considérable. A prétendre en effet décrire le monde tel qu'il est, on lui substitue simplement ce qu'on veut qu'il soit. Implicitement ou réellement les issues sont bloquées les unes après les autres, jusqu'à exclure, nier tout ce qui, par nature, se soustrait à cette emprise objective. [...] Proposition monstrueuse qui, à vouloir dire la vérité de tous, nie la vérité de chacun. Et non sans raison : en déterminant caractère, type, filiation, milieu, on a pour but de quadriller et de maîtriser toute la réalité. C'est le règne de la classification avant d'être celui de la police.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "A en croire la critique extasiée, le monde de Balzac serait encore celui où nous vivons. Mais ne serait-ce pas parce que Balzac, profondément acquis à ce monde-là, a engagé ses prodigieuses qualités d'observateur à en asseoir les fondements ? Une fois le sens ainsi fixé, c'est le plus et le moins, l'économie et la dépense qui vont écrire l'histoire et les histoires. Par bonheur, Balzac joue le jeu jusqu'au bout : en cherchant à dépister la raison de la folie, il rencontre en chemin la folie de la raison. Trop passionné serviteur de la raison marchande, le voilà qui se laisse emporter par la folie du nombre. Et c'est cette seule folie qui fait sa grandeur, qui transforme l'observateur en visionnaire, éclairant parfois le réel de tous les feux de ce qui n'est pas. Néanmoins, on ne saurait se laisser abuser par la stature du personnage : c'est avec lui et par lui que le roman commence à se confondre avec le bilan. Bilan d'une époque, bilan d'une société, bilan d'une vie. Le monde de l'argent a trouvé son genre littéraire par excellence qui répercutera ses brillances, ses brutalités, ses subtilités, ses cruautés, ses contradictions dans l'espace de la fiction. Jusqu'à ce que la raison marchande en crise au début du XXe siècle dépose son bilan en même temps que ses romans.", Author = "Honoré de Balzac" },
        };
    }
}